-- Application EN LIGNE des données de départ du référentiel Cultiplan (version 2026-11-27), projet redtuedpnhbqziqmyyjc.
-- GÉNÉRÉ par scripts/generer-sql-referentiel.mjs à partir de supabase/donnees/referentiel-depart.json. Toutes les lignes sont en brouillon_ia.
-- Une transaction. Rejouable : une ligne déjà relue (statut autre que brouillon_ia) n'est jamais écrasée.
-- Prérequis : schéma ref complet, et questions de terrain (20261127_ref_entretien_donnees.sql) appliqués avant.
BEGIN;

-- speculations : 10 ligne(s)
INSERT INTO ref.speculations ("code", "nom", "secteur", "sous_secteur", "unite_echelle", "duree_cycle_jours", "cycles_par_an", "zones", "statut", "source")
SELECT "code", "nom", "secteur", "sous_secteur", "unite_echelle", "duree_cycle_jours", "cycles_par_an", "zones", "statut", "source" FROM jsonb_populate_recordset(NULL::ref.speculations, $donnees$[{"code":"tomate","nom":"Tomate","secteur":"vegetal","sous_secteur":"maraichage","unite_echelle":"ha","duree_cycle_jours":70,"cycles_par_an":1,"zones":["maritime","plateaux","centrale"],"statut":"brouillon_ia","source":"Agripilot, filieres.json (maraichage-tomates). Mois de décaissement et de vente : hypothèse Cultiso d'après la durée du cycle."},{"code":"piment","nom":"Piment","secteur":"vegetal","sous_secteur":"maraichage","unite_echelle":"ha","duree_cycle_jours":90,"cycles_par_an":1,"zones":["maritime","plateaux","centrale","kara"],"statut":"brouillon_ia","source":"Agripilot, filieres.json (maraichage-piments). Mois : hypothèse Cultiso d'après la durée du cycle."},{"code":"oignon","nom":"Oignon","secteur":"vegetal","sous_secteur":"maraichage","unite_echelle":"ha","duree_cycle_jours":120,"cycles_par_an":1,"zones":["maritime","savanes","kara"],"statut":"brouillon_ia","source":"Agripilot, filieres.json (maraichage-oignon). Mois : hypothèse Cultiso d'après la durée du cycle."},{"code":"mais","nom":"Maïs","secteur":"vegetal","sous_secteur":"cultures_vivrieres","unite_echelle":"ha","duree_cycle_jours":90,"cycles_par_an":1,"zones":["maritime","plateaux","centrale","kara","savanes"],"statut":"brouillon_ia","source":"Agripilot, filieres.json (cultures-vivrieres-mais). Semences à 600 FCFA/kg dans Agripilot, 1 500 à 2 000 FCFA/kg dans le Stimulateur : à trancher. Mois : hypothèse Cultiso."},{"code":"soja","nom":"Soja","secteur":"vegetal","sous_secteur":"cultures_vivrieres","unite_echelle":"ha","duree_cycle_jours":null,"cycles_par_an":1,"zones":["kara"],"statut":"brouillon_ia","source":"Stimulateur, calculations.js (barème Soja : préparation 90 000, intrants 140 000 FCFA/ha, 1,2 t/ha) et countries.js (Togo : soja 300 à 500 FCFA/kg, moyenne 400). Scénarios : coefficients du Stimulateur (0,7 débutant, 1,5 bon). Détail des postes, durée du cycle et mois : à compléter."},{"code":"poulet_chair","nom":"Poulet de chair","secteur":"animal","sous_secteur":"aviculture","unite_echelle":"sujet","duree_cycle_jours":45,"cycles_par_an":4,"zones":["maritime","plateaux","centrale","kara","savanes"],"statut":"brouillon_ia","source":"Agripilot, filieres.json (elevage-volaille-poulets), lot de 200 ramené à 1 sujet ; Stimulateur (4 cycles par an, mortalité 5 %, bâtiment 3 500 FCFA par tête, équipement 150 000 FCFA, ramené ici à un lot de 500). Durées de vie : hypothèse Cultiso."},{"code":"poule_pondeuse","nom":"Poules pondeuses","secteur":"animal","sous_secteur":"aviculture","unite_echelle":"poule","duree_cycle_jours":365,"cycles_par_an":1,"zones":["maritime","plateaux","centrale"],"statut":"brouillon_ia","source":"Agripilot, filieres.json (elevage-pondeuses), lot de 100 ramené à 1 poule ; Stimulateur (bâtiment 4 500 FCFA par tête, équipement 200 000 FCFA, ramené ici à un lot de 100 ; 240 œufs et 8 % de mortalité, non repris car le rendement d'Agripilot est déjà par poule logée). Aliment : 3,5 kg par poule et par mois (Stimulateur), car les 20 sacs par mois pour 100 poules d'Agripilot font 333 g par jour, trois fois la ration habituelle. Durées de vie : hypothèse Cultiso. Poules de réforme (coproduit) : à ajouter."},{"code":"tilapia","nom":"Tilapia en étang","secteur":"halieutique","sous_secteur":"pisciculture","unite_echelle":"étang de 5 000 alevins","duree_cycle_jours":180,"cycles_par_an":2,"zones":["maritime","plateaux","centrale"],"statut":"brouillon_ia","source":"Agripilot, filieres.json (pisciculture-tilapia). Deux cycles par an déduits de la durée du cycle (180 jours). Construction de l'étang non comprise (Stimulateur : 800 FCFA par alevin, à valider). Durées de vie : hypothèse Cultiso."},{"code":"gari","nom":"Gari de manioc","secteur":"transformation","sous_secteur":"transformation_manioc","unite_echelle":"fournée de 500 kg de manioc","duree_cycle_jours":7,"cycles_par_an":40,"zones":["maritime","plateaux","centrale"],"statut":"brouillon_ia","source":"Agripilot, filieres.json (transformation-gari-manioc), modèle artisanal avec râpe louée. 40 fournées par an : hypothèse Cultiso à valider. Unité semi-industrielle (Stimulateur : équipement 2,5 M, aménagement 0,6 M FCFA) non reprise."},{"code":"embouche_ovine","nom":"Embouche de petits ruminants (moutons)","secteur":"animal","sous_secteur":"elevage_ruminants","unite_echelle":"tête","duree_cycle_jours":180,"cycles_par_an":2,"zones":["plateaux","centrale","kara","savanes"],"statut":"brouillon_ia","source":"Stimulateur, calculations.js (Ovins : 2 cycles par an, mortalité 5 %, 180 kg d'aliment par tête, bâtiment 35 000 FCFA par tête, équipement 80 000 FCFA, ramené ici à un lot de 20) et countries.js (Togo : agneau 45 000 à 75 000, agneau vendu 80 000 à 150 000, botte de foin 500 à 1 000 FCFA). Vaccination : Agripilot (elevage-caprins). Botte de 15 kg, durées de vie et absence d'écart entre scénarios : hypothèses Cultiso à valider."}]$donnees$::jsonb)
ON CONFLICT ("code") DO UPDATE SET "nom" = EXCLUDED."nom", "secteur" = EXCLUDED."secteur", "sous_secteur" = EXCLUDED."sous_secteur", "unite_echelle" = EXCLUDED."unite_echelle", "duree_cycle_jours" = EXCLUDED."duree_cycle_jours", "cycles_par_an" = EXCLUDED."cycles_par_an", "zones" = EXCLUDED."zones", "statut" = EXCLUDED."statut", "source" = EXCLUDED."source"
WHERE ref.speculations.statut = 'brouillon_ia';

